<?php
namespace App\Http\Controllers;
use App\Models\{ActivityLog,Attendance,Department,Employee,Payroll,Position};
use Illuminate\Http\Request;
use Inertia\Inertia;
use Inertia\Response;
class AdminController extends Controller { private function shared(): array { return ['departments'=>Department::orderBy('department_name')->get(),'positions'=>Position::orderBy('position_name')->get()]; } public function dashboard(): Response { $employees=Employee::where('is_active',1)->count(); $present=Attendance::whereDate('attendance_date',today())->whereNotNull('time_in')->distinct('employee_id')->count('employee_id'); return Inertia::render('Admin/Dashboard',['stats'=>['total_employees'=>$employees,'present_today'=>$present,'absent_today'=>max(0,$employees-$present),'payrolls_processed'=>Payroll::count(),'total_departments'=>Department::count()],'activities'=>ActivityLog::latest('timestamp')->limit(8)->get()]); } public function employees(Request $request): Response { return Inertia::render('Admin/Employees',$this->shared()+['employees'=>Employee::with(['department','position','user'])->when($request->search,fn($q,$v)=>$q->where(fn($q)=>$q->where('first_name','like',"%$v%")->orWhere('last_name','like',"%$v%")->orWhere('employee_code','like',"%$v%")))->latest('employee_id')->paginate(8)->withQueryString()]); } public function organization(): Response { return Inertia::render('Admin/Organization',$this->shared()); } public function attendance(Request $request): Response { return Inertia::render('Admin/Attendance',$this->shared()+['attendance'=>Attendance::with('employee.department')->latest('attendance_date')->paginate(10)->withQueryString()]); } public function payroll(Request $request): Response { return Inertia::render('Admin/Payroll',$this->shared()+['employees'=>Employee::active()->orderBy('last_name')->get(),'payrolls'=>Payroll::with('employee.department')->latest('processed_date')->paginate(10)]); } public function report(string $type): Response { $rows=match($type){'attendance'=>Attendance::with('employee.department')->latest('attendance_date')->limit(1000)->get(),'payroll'=>Payroll::with('employee.department')->latest('processed_date')->limit(1000)->get(),default=>Employee::with(['department','position'])->latest('employee_id')->limit(1000)->get()}; return Inertia::render('Reports/Index',['type'=>$type,'rows'=>$rows]+$this->shared()); } }
